#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Configure WLED master/slave (UDP) sync so every device shows the same effect.

How WLED sync works (verified against the firmware source):
  * Master  : if.sync.send.en = true, if.sync.send.grp = <group bitmask>,
              if.sync.send.dir = true  -> broadcasts on every HTTP/UI change
  * Slaves  : if.sync.recv.* = true, if.sync.recv.grp = <same group bitmask>
  * Transport: UDP broadcast on port0 (21324) inside the same subnet.
  * IMPORTANT: the notification carries the raw effect ID, so all devices should
    run the same WLED version, otherwise the effect lands on the wrong FX.

Usage:
    python3 scripts/sync_devices.py --status
    python3 scripts/sync_devices.py --setup                    # first device = master
    python3 scripts/sync_devices.py --setup --master 192.168.2.9
    python3 scripts/sync_devices.py --setup --ips 192.168.2.9,192.168.2.10 --group 1
    python3 scripts/sync_devices.py --selftest                 # prove the broadcast happens
    python3 scripts/sync_devices.py --disable                  # turn sync off everywhere

Two gates must both be on for the master to actually broadcast, and only the
first is visible in the sync settings page:
    if.sync.send.en      (config)  -> sendNotifications
    state.udpn.send      (runtime) -> sendNotificationsRT, what notify() checks
--setup writes both; --selftest verifies with a real packet.

Output: JSON with {success, master, slaves, group, results, verified}
"""
import json
import os
import sys
import time
import urllib.error
import urllib.request

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
SKILL_DIR = os.path.dirname(SCRIPT_DIR)
sys.path.insert(0, SCRIPT_DIR)

DEFAULT_GROUP = 1  # bit0 -> "group 1" in the WLED UI


def load_config():
    with open(os.path.join(SKILL_DIR, "config.json"), "r", encoding="utf-8") as f:
        return json.load(f)


def get_wled_ip():
    """Health-checked WLED IP via discover_wled.resolve_ip().

    The raw .wled_cache.json is deliberately NOT read here: a stale cache used
    to be returned unverified, which sent writes to an offline device.
    """
    try:
        if SCRIPT_DIR not in sys.path:
            sys.path.insert(0, SCRIPT_DIR)
        import discover_wled
        return discover_wled.resolve_ip()
    except Exception:
        return load_config().get("wled", {}).get("ip", "")


def wled_request(ip, path, method="GET", data=None, timeout=6):
    url = "http://{}{}".format(ip, path)
    req = urllib.request.Request(url, headers={"User-Agent": "DoubaoWledSkill/1.0"})
    if method == "POST" and data is not None:
        req.data = json.dumps(data).encode("utf-8")
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            body = resp.read().decode("utf-8")
            try:
                return json.loads(body) if body else {}
            except json.JSONDecodeError:
                return {"raw": body}
    except urllib.error.HTTPError as e:
        return {"error": "HTTP {}".format(e.code)}
    except Exception as e:
        return {"error": str(e)}


def read_sync(ip):
    """Return the current if.sync config block (or {} on failure)."""
    cfg = wled_request(ip, "/json/cfg")
    if isinstance(cfg, dict) and "if" in cfg:
        return cfg.get("if", {}).get("sync", {}) or {}
    return {}


def read_live_cfg(ip):
    """Return if.live — needed because `mso` disables the realtime override.

    cfg.cpp maps if.live.mso -> useMainSegmentOnly, and json.cpp does:
        if (realtimeMode && useMainSegmentOnly) realtimeOverride = REALTIME_OVERRIDE_NONE;
    i.e. with "Live segment only" enabled the lor=2 override is silently
    ignored, and no recipe can win against an incoming stream.
    """
    cfg = wled_request(ip, "/json/cfg")
    if isinstance(cfg, dict) and "if" in cfg:
        return cfg.get("if", {}).get("live", {}) or {}
    return {}


def read_runtime_send(ip):
    """Return the RUNTIME notification gate (state.udpn.send).

    This is the trap that makes sync look configured but stay silent:
      * notify() bails on `!syncGroups || !sendNotificationsRT` (udp.cpp:27).
      * if.sync.send.en only sets the *config* value `sendNotifications`;
        cfg.cpp copies it into `sendNotificationsRT`, whose _INIT is false.
      * The runtime flag is settable straight from the state API:
        POST /json/state {"udpn":{"send":true}} (json.cpp:428), and it is what
        /json/state reports back as `udpn.send`.
    So a device can show if.sync.send.en=true in its config and still never
    broadcast. Always check/report this one too.
    """
    st = wled_request(ip, "/json/state")
    if isinstance(st, dict) and isinstance(st.get("udpn"), dict):
        return bool(st["udpn"].get("send"))
    return None


def enable_runtime_send(ip, group=DEFAULT_GROUP):
    """Turn on the runtime notification gate + put the device in the group."""
    return wled_request(ip, "/json/state", method="POST",
                        data={"udpn": {"send": True, "sgrp": int(group), "rgrp": int(group)}})


def write_sync(ip, sync_block):
    """POST the merged if.sync block back to the device."""
    return wled_request(ip, "/json/cfg", method="POST", data={"if": {"sync": sync_block}})


def _merge_recv(sync, enabled, group):
    """Build the recv block.

    `seg` and `sb` are the ones that usually matter and are OFF by default on a
    fresh WLED (measured: {"bri":true,"col":true,"fx":true,"pal":true,
    "grp":1,"seg":false,"sb":false}). With recv.seg disabled a slave applies the
    effect but NOT the segment layout, so a four-edge TV recipe arrives as one
    full-strip effect - visibly not the same picture. Always enable all six.
    """
    recv = dict(sync.get("recv") or {})
    for key in ("bri", "col", "fx", "pal", "seg", "sb"):
        recv[key] = bool(enabled)
    recv["grp"] = int(group)
    return recv


def _merge_send(sync, enabled, group):
    send = dict(sync.get("send") or {})
    send["en"] = bool(enabled)
    if enabled:
        send["dir"] = True          # notify on direct HTTP/UI changes
        send["grp"] = int(group)    # group bitmask we broadcast to
    return send


def configure_master(ip, group=DEFAULT_GROUP):
    """Make `ip` the sync master (broadcasts on every change).

    Only the `send` half of if.sync is written. The `recv` half is left exactly
    as the device already had it: forcing it off used to be this function's
    behaviour and it silently removed the device from its own group, so a change
    made on a slave or by a button could no longer reach it. Receiving is
    harmless - an incoming notification is applied with CALL_MODE_NOTIFICATION,
    which does not re-broadcast, so there is no echo loop.

    The config write alone is NOT enough to make the device talk: the runtime
    gate `sendNotificationsRT` (state.udpn.send) also has to be on. Both are set
    here, and both are reported back so the caller can verify.
    """
    sync = read_sync(ip)
    recv_before = dict(sync.get("recv") or {})
    sync["send"] = _merge_send(sync, True, group)
    resp = write_sync(ip, sync)
    rt = enable_runtime_send(ip, group)
    readback = read_sync(ip)
    return {"ip": ip, "role": "master", "group": group, "response": resp,
            "recv_kept": recv_before,
            "runtime_send_response": rt,
            "verified_config_send": (readback.get("send") or {}),
            "verified_runtime_send": read_runtime_send(ip),
            "success": "error" not in (resp or {}) and "error" not in (rt or {})}


def configure_slave(ip, group=DEFAULT_GROUP):
    """Make `ip` a sync slave (mirrors the master).

    A slave sitting in realtime mode ignores notifications outright
    (udp.cpp: `if (udpIn[0] == 0 && !realtimeMode && receiveGroups)`), so clear
    realtime and any stale override before enabling recv.
    """
    sync = read_sync(ip)
    sync["recv"] = _merge_recv(sync, True, group)
    sync["send"] = _merge_send(sync, False, group)
    resp = write_sync(ip, sync)

    live_reset = None
    try:
        from apply_recipe import release_realtime_override
        live_reset = release_realtime_override(ip)
    except Exception as exc:
        live_reset = {"error": str(exc)}

    return {"ip": ip, "role": "slave", "group": group, "response": resp,
            "live_reset": live_reset,
            "success": "error" not in (resp or {})}


def disable_sync(ip):
    sync = read_sync(ip)
    sync["recv"] = _merge_recv(sync, False, 0)
    sync["send"] = _merge_send(sync, False, 0)
    resp = write_sync(ip, sync)
    return {"ip": ip, "role": "off", "response": resp, "success": "error" not in (resp or {})}


def status(ips):
    out = []
    for ip in ips:
        sync = read_sync(ip)
        if not sync:
            out.append({"ip": ip, "online": False})
            continue
        live = read_live_cfg(ip)
        send = sync.get("send") or {}
        recv = sync.get("recv") or {}
        rt_send = read_runtime_send(ip)
        seg_on = bool(recv.get("seg"))
        out.append({
            "ip": ip,
            "online": True,
            "send_enabled": bool(send.get("en")),
            "send_group": send.get("grp"),
            "recv_group": recv.get("grp"),
            "recv_segments": seg_on,
            # the two gates that actually decide whether this device talks
            "runtime_send": rt_send,
            "broadcast_ready": bool(send.get("en")) and rt_send is not False,
            "role": ("master" if send.get("en")
                     else ("slave" if recv.get("fx") else "off")),
            "live_segment_only": bool(live.get("mso")),
            "override_available": not bool(live.get("mso")),
        })
    return out


def selftest(ip, group=DEFAULT_GROUP, timeout=6):
    """Prove on THIS LAN that a write to `ip` really produces a sync broadcast.

    Useful because a single-device setup gives no other way to see it, and
    because the two silent failure modes (config switch on but runtime gate off;
    or nothing actually changing) look identical from the HTTP side.

    Binds UDP 21324 locally and triggers a real state change on the device.
    Note: WLED only notifies when `bri != briOld || stateChanged` (led.cpp:95),
    so a repeat of the identical state legitimately broadcasts nothing.
    """
    import socket
    import threading

    st = wled_request(ip, "/json/state")
    bri_now = st.get("bri", 128) if isinstance(st, dict) else 128
    # alternate the brightness so this is always a real change
    bri_new = bri_now + 7 if bri_now < 240 else bri_now - 7

    packets = []

    def listen():
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            s.bind(("", 21324))
        except OSError as exc:
            packets.append(("bind_error", str(exc)))
            return
        s.settimeout(timeout)
        end = time.time() + timeout
        while time.time() < end:
            try:
                data, addr = s.recvfrom(2048)
                packets.append((addr[0], data))
            except socket.timeout:
                break
        s.close()

    t = threading.Thread(target=listen, daemon=True)
    t.start()
    time.sleep(0.4)
    wled_request(ip, "/json/state", method="POST", data={"on": True, "bri": bri_new})
    t.join(timeout + 1)

    bind_error = next((p[1] for p in packets if p[0] == "bind_error"), None)
    datagrams = [p for p in packets if p[0] != "bind_error"]
    decoded = None
    for src, d in datagrams:
        if len(d) > 41 and d[0] == 0:
            decoded = {"from": src, "len": len(d), "callMode": d[1], "bri": d[2],
                       "fx": d[8], "sx": d[9], "sync_group": d[36],
                       "segment_count": d[39]}
            break

    ok = bool(decoded)
    out = {
        "success": ok,
        "ip": ip,
        "group": group,
        "packets_seen": len(datagrams),
        "broadcast_decoded": decoded,
        "message": ("本机已收到来自 {} 的同步广播，主从同步链路成立".format(ip) if ok
                    else "未收到同步广播：请检查 if.sync.send.en、state.udpn.send 与同步组，"
                         "并确认本次状态确实发生了变化"),
    }
    if bind_error:
        out["success"] = False
        out["message"] = "本机无法监听 UDP 21324（{}），自检未执行".format(bind_error)
    elif not ok:
        stt = wled_request(ip, "/json/state")
        out["diagnostics"] = {
            "if_sync_send_en": bool((read_sync(ip).get("send") or {}).get("en")),
            "state_udpn_send": (stt.get("udpn") or {}).get("send") if isinstance(stt, dict) else None,
            "state_bri_before": bri_now,
            "state_bri_written": bri_new,
        }
    return out


def setup_sync(ips=None, master=None, group=DEFAULT_GROUP):
    """Configure one master and the rest as slaves."""
    from guard import require_write
    blocked = require_write(action="sync_devices")
    if blocked:
        return blocked

    if not ips:
        ips = [get_wled_ip()]
        if not ips[0]:
            return {"success": False, "message": "No WLED IP configured. Add --ips or run discover_wled.py"}
    ips = [ip.strip() for ip in ips if ip and ip.strip()]
    if not ips:
        return {"success": False, "message": "No valid IPs provided"}

    master_ip = master or ips[0]
    slaves = [ip for ip in ips if ip != master_ip]

    results = [configure_master(master_ip, group=group)]
    for ip in slaves:
        results.append(configure_slave(ip, group=group))

    ok = all(r.get("success") for r in results)

    # Read back what the devices actually stored - write_sync() returning 200 is
    # not proof that if.sync was parsed.
    verified = status(ips)

    warnings = []
    for v in verified:
        if v.get("live_segment_only"):
            warnings.append(
                "{}: 「Live segment only」(if.live.mso) 为开启状态，WLED 会忽略 lor 优先级，"
                "外部实时流无法被光配方抢占。如需优先级接管请先在设备上关闭该项。".format(v["ip"])
            )
        if v["ip"] == master_ip and not v.get("broadcast_ready"):
            warnings.append(
                "{}: 主设备广播未就绪（if.sync.send.en={} / state.udpn.send={}）。"
                "两者都为真时 WLED 才会真正发包，只写 if.sync 会在运行时静默不广播。".format(
                    v["ip"], v.get("send_enabled"), v.get("runtime_send"))
            )
    for r in results:
        if r.get("role") == "master" and not r.get("verified_runtime_send"):
            warnings.append(
                "{}: 运行时通知开关未确认打开；请执行 --selftest 实测一次广播。".format(r.get("ip"))
            )
    if len(ips) == 1:
        warnings.append("当前只配置了 1 台设备，已按 master 写入发送组；接入第 2 台后重跑 --setup 即可自动编入从设备。")
    for r in results:
        if r.get("role") == "slave" and not (r.get("recv") or {}).get("seg"):
            warnings.append("{}: 从设备未开启段同步(recv.seg)，四段式光配方会退化成整条同色。".format(r.get("ip")))

    out = {
        "success": ok,
        "master": master_ip,
        "slaves": slaves,
        "group": group,
        "results": results,
        "verified": verified,
        "note": ("All devices must run the same WLED version: the sync packet carries the "
                 "raw FX id, so a version mismatch lands on the wrong effect."),
        "message": ("Sync configured: master={} group={} slaves={}".format(master_ip, group, slaves)
                    if ok else "One or more sync writes failed — check the results"),
    }
    if warnings:
        out["warnings"] = warnings
    return out


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        sys.exit(0)

    ips = None
    if "--ips" in sys.argv:
        idx = sys.argv.index("--ips") + 1
        if idx < len(sys.argv):
            ips = sys.argv[idx].split(",")
    group = DEFAULT_GROUP
    if "--group" in sys.argv:
        idx = sys.argv.index("--group") + 1
        if idx < len(sys.argv):
            group = int(sys.argv[idx])
    master = None
    if "--master" in sys.argv:
        idx = sys.argv.index("--master") + 1
        if idx < len(sys.argv):
            master = sys.argv[idx]

    if "--disable" in sys.argv:
        from guard import require_write
        blocked = require_write(action="sync_disable")
        if blocked:
            print(json.dumps(blocked, indent=2, ensure_ascii=False)); sys.exit(1)
        targets = ips or [get_wled_ip()]
        res = [disable_sync(ip) for ip in targets if ip]
        print(json.dumps({"success": all(r.get("success") for r in res), "results": res},
                         indent=2, ensure_ascii=False))
        sys.exit(0)

    if "--setup" in sys.argv:
        result = setup_sync(ips=ips, master=master, group=group)
        print(json.dumps(result, indent=2, ensure_ascii=False))
        sys.exit(0 if result.get("success") else 1)

    if "--selftest" in sys.argv:
        target = master or (ips[0] if ips else get_wled_ip())
        if not target:
            print(json.dumps({"success": False, "message": "No WLED IP configured"}, ensure_ascii=False))
            sys.exit(1)
        result = selftest(target, group=group)
        print(json.dumps(result, indent=2, ensure_ascii=False))
        sys.exit(0 if result.get("success") else 1)

    # default / --status
    targets = ips or [get_wled_ip()]
    print(json.dumps({"success": True, "devices": status([t for t in targets if t])},
                     indent=2, ensure_ascii=False))
    sys.exit(0)


if __name__ == "__main__":
    main()
# AI: end
